def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    import subprocess
    import os
    from itertools import islice
    from typing import Sequence, Any
    from threading import Thread
    from queue import Queue, Empty

    def run_command(command: tuple[str, ...]) -> tuple[int, bytes]:
        try:
            result = subprocess.run(command, check=False, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
            return result.returncode, result.stdout
        except Exception as e:
            return -1, str(e).encode()

    def worker(command_queue: Queue, results_queue: Queue):
        while True:
            command = command_queue.get()
            if command is None:
                break
            results_queue.put(run_command(command))
            command_queue.task_done()

    if target_concurrency < 1:
        raise ValueError("target_concurrency must be at least 1")

    command_queue = Queue()
    results_queue = Queue()

    threads = []
    for _ in range(target_concurrency):
        thread = Thread(target=worker, args=(command_queue, results_queue), daemon=True)
        thread.start()
        threads.append(thread)

    current_length = 0
    current_command = list(cmd)
    for arg in varargs:
        if color and os.name == 'posix':
            arg = f"\033[1;34m{arg}\033[0m"
        new_length = current_length + len(arg) + len(cmd) + 1  # +1 for space or end of command
        if new_length > _max_length:
            command_queue.put(tuple(current_command))
            current_command = list(cmd)
            current_length = 0
        current_command.append(arg)
        current_length += len(arg) + 1

    if current_command != list(cmd):
        command_queue.put(tuple(current_command))

    command_queue.join()

    for _ in threads:
        command_queue.put(None)
    for thread in threads:
        thread.join()

    final_returncode = 0
    final_output = b""
    while not results_queue.empty():
        returncode, output = results_queue.get()
        final_returncode = final_returncode or returncode
        final_output += output + b"\n"

    return final_returncode, final_output.strip()

