def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    try:
        if not cmd or not isinstance(cmd, tuple) or not all(isinstance(arg, str) for arg in cmd):
            raise ValueError("cmd must be a non-empty tuple of strings")

        # Check for shebang and modify the command if necessary
        if cmd[0].startswith('#!'):
            # Split the shebang line to extract the interpreter
            shebang_parts = cmd[0].split()
            interpreter = shebang_parts[0][2:]  # Remove '#!' from the start
            # Create a new command with the interpreter and the rest of the shebang arguments
            new_cmd = (interpreter,) + tuple(shebang_parts[1:]) + cmd[1:]
            return new_cmd

        # If no shebang, return the command as is
        return cmd

    except Exception as e:
        raise RuntimeError(f"An error occurred while normalizing the command: {e}")

