def _legacy_mergeOrderings(orderings):
    try:
        if not isinstance(orderings, list) or not all(isinstance(ordering, list) for ordering in orderings):
            raise ValueError("Input must be a list of lists.")

        merged = []
        suffix_map = {}

        for ordering in orderings:
            for i, elem in enumerate(ordering):
                if elem not in suffix_map:
                    suffix_map[elem] = []
                suffix_map[elem].extend(ordering[i+1:])

        for ordering in orderings:
            for i, elem in enumerate(ordering):
                if elem in merged:
                    continue
                merged.append(elem)
                suffix_to_add = suffix_map.get(elem, [])
                for suffix_elem in suffix_to_add:
                    if suffix_elem not in merged:
                        merged.append(suffix_elem)

        return merged

    except Exception as e:
        print(f"An error occurred: {e}")
        return []

def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    try:
        merged_ordering = []
        position_map = {}
        for ordering in orderings:
            for index, item in enumerate(ordering):
                if item not in position_map:
                    position_map[item] = index
                else:
                    position_map[item] = min(position_map[item], index)

        for ordering in orderings:
            merged_ordering.extend([item for item in ordering if item not in merged_ordering])

        return merged_ordering
    except Exception as e:
        raise ValueError(f"An error occurred while merging orderings: {e}")

