def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        # Create a set to track classes that are not needed
        redundant = set()
        # Iterate over the list of classes
        for i, cls in enumerate(classes):
            # Check if the current class is a subclass of any subsequent classes
            for j in range(i + 1, len(classes)):
                if issubclass(cls, classes[j]):
                    redundant.add(cls)
                    break
        # Return a list of classes that are not redundant
        return [cls for cls in classes if cls not in redundant]
    except TypeError:
        # Handle the case where the input is not a list of classes
        raise ValueError("Input must be a list of class objects")

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        # Create a set to track visited classes and a list for the minimal bases
        visited = set()
        minimal = []

        # Helper function to perform depth-first search
        def dfs(cls):
            if cls not in visited:
                visited.add(cls)
                for base in cls.__bases__:
                    dfs(base)
                minimal.append(cls)

        # Perform DFS for each class in the input list
        for cls in classes:
            dfs(cls)

        # Reverse the minimal list to get the correct order
        minimal.reverse()

        # Remove duplicates while maintaining order
        seen = set()
        ordered_minimal = []
        for cls in minimal:
            if cls not in seen:
                seen.add(cls)
                ordered_minimal.append(cls)

        return ordered_minimal

    except AttributeError as e:
        # Handle the case where the input list contains non-class elements
        raise ValueError("All elements in the input list must be class objects.") from e
    except Exception as e:
        # Handle any other unexpected exceptions
        raise RuntimeError("An unexpected error occurred.") from e

