def to_csv(self, separator=",", header=None):
    try:
        if not isinstance(separator, str):
            raise ValueError("Separator must be a string.")

        csv_lines = []

        if header is not None:
            if not isinstance(header, str):
                raise ValueError("Header must be a string or None.")
            csv_lines.append(header)

        for point in self.points:
            if not isinstance(point, tuple) or len(point) != 2:
                raise ValueError("Each point must be a tuple of (coordinates, values).")

            coords, values = point
            if not isinstance(coords, tuple) or not isinstance(values, tuple):
                raise ValueError("Coordinates and values in each point must be tuples.")

            coord_str = separator.join(map(str, coords))
            value_str = separator.join(map(str, values))
            csv_lines.append(f"{coord_str}{separator}{value_str}")

        return "\n".join(csv_lines)

    except Exception as e:
        return f"An error occurred: {str(e)}"

