def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    try:
        if isinstance(params, Mapping):
            out_params = {f":{key}": value for key, value in params.items()}
            formatted_sql = sql
            for key in params:
                placeholder = f"${key}" if isinstance(key, int) else f"%({key})"
                formatted_sql = formatted_sql.replace(placeholder, f":{key}")
        elif isinstance(params, Sequence):
            out_params = [value for value in params]
            formatted_sql = sql
            for i in range(len(params)):
                formatted_sql = formatted_sql.replace(f"${i + 1}", f":{i + 1}")
        else:
            raise ValueError("params must be a mapping or a sequence")

        return formatted_sql, out_params

    except Exception as e:
        raise RuntimeError(f"An error occurred during SQL formatting: {e}")

def formatmany(
		self,
		sql: AnyStr,
		many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
		out_style_sql = sql
		converted_params = []

		try:
			for params in many_params:
				if isinstance(params, Mapping):
					# Assuming named parameter style
					out_style_sql = re.sub(r':([a-zA-Z_]\w*)', r'%(\1)s', out_style_sql)
					converted_params.append(params)
				elif isinstance(params, Sequence):
					# Assuming ordinal parameter style
					out_style_sql = re.sub(r'\?', r'%s', out_style_sql)
					converted_params.append(list(params))
				else:
					raise ValueError("Invalid parameter type")
		except Exception as e:
			raise ValueError(f"Error in formatting SQL: {e}")

		return out_style_sql, converted_params

def formatmany(
		self,
		sql: AnyStr,
		many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
		out_style_sql = sql
		converted_params = []

		for params in many_params:
			if isinstance(params, Mapping):
				# Assuming named parameters style
				out_style_sql = re.sub(r':([a-zA-Z_]\w*)', r'%(\1)s', sql)
				converted_params.append(params)
			elif isinstance(params, Sequence):
				# Assuming ordinal parameters style
				out_style_sql = re.sub(r'%.+?s', r'%s', sql)
				converted_params.append(list(params))
			else:
				raise ValueError("Parameters must be either a Mapping or a Sequence")

		return out_style_sql, converted_params

