def _explore_folder(folder):
    import os
    import xml.etree.ElementTree as ET

    if not isinstance(folder, str):
        raise ValueError("The folder parameter must be a string.")

    if not os.path.isdir(folder):
        raise FileNotFoundError(f"The specified folder {folder} does not exist or is not a directory.")

    packages_data = {}

    try:
        for filename in os.listdir(folder):
            if filename.endswith('.xml'):
                filepath = os.path.join(folder, filename)
                tree = ET.parse(filepath)
                root = tree.getroot()
                base_name = os.path.splitext(filename)[0]
                if base_name not in packages_data:
                    packages_data[base_name] = []
                packages_data[base_name].append(ET.tostring(root, encoding='unicode'))
    except ET.ParseError as e:
        raise ValueError(f"Error parsing XML file: {e}")
    except Exception as e:
        raise Exception(f"An unexpected error occurred: {e}")

    return packages_data

