def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os

    if not isinstance(zip_path, str):
        raise ValueError("zip_path must be a string")

    if not zipfile.is_zipfile(zip_path):
        raise ValueError("Invalid zip file")

    try:
        with zipfile.ZipFile(zip_path, 'r') as z:
            file_dict = {}
            for file_info in z.infolist():
                if file_info.filename.endswith('.xml'):
                    base_name = os.path.splitext(os.path.basename(file_info.filename))[0]
                    if base_name not in file_dict:
                        file_dict[base_name] = []
                    file_dict[base_name].append(file_info.filename)
            return file_dict
    except Exception as e:
        raise RuntimeError(f"An error occurred while processing the zipfile: {e}")

def _explore_zipfile(zip_path):
    import os
    import zipfile
    from collections import defaultdict

    if not isinstance(zip_path, str):
        raise ValueError("zip_path must be a string")

    if not os.path.exists(zip_path):
        raise FileNotFoundError(f"The file at {zip_path} does not exist")

    if not zipfile.is_zipfile(zip_path):
        raise ValueError("The file at {zip_path} is not a valid zip file")

    grouped_data = defaultdict(list)

    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            for file_info in zip_ref.infolist():
                if file_info.filename.endswith('.xml'):
                    basename = os.path.splitext(os.path.basename(file_info.filename))[0]
                    with zip_ref.open(file_info) as file:
                        content = file.read()
                    grouped_data[basename].append(content)
    except Exception as e:
        raise Exception(f"An error occurred while processing the zipfile: {str(e)}")

    return dict(grouped_data)

