def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    try:
        issue = issue.strip().lower()
        number, suppl = None, None

        # Check for direct mappings
        if 'suppl' in issue or 'spe' in issue or 's' in issue:
            suppl = 'suppl'

        # Extract number
        if issue.replace('.', '', 1).isdigit() or '-' in issue:
            number = issue.split('suppl')[0].split('spe')[0].split('s')[0].split()[0].replace('.', '')

        # Clean up number
        if number and not number.isdigit():
            number = number.split('-')[0]  # Take first part if range

        # Handle special cases
        if 'suppl' in issue or 'spe' in issue or 's' in issue:
            suppl_parts = issue.split()
            for part in suppl_parts:
                if 'suppl' in part:
                    suppl = 'suppl'
                    break
                elif 'spe' in part or 's' in part:
                    suppl = 'spe'
                    break

            if len(suppl_parts) > 1:
                for part in suppl_parts[1:]:
                    if part.isdigit() or '-' in part:
                        suppl += ' ' + part
                        break

        return number, suppl

    except Exception as e:
        print(f"Error processing issue element: {e}")
        return None, None

