def _fromutc(self, dt):
    if dt.tzinfo is None:
        raise ValueError("dt must be a timezone-aware datetime object")

    try:
        # Calculate the timezone-aware datetime in the new timezone
        new_dt = dt.astimezone(self)

        # Check if the datetime is in a fold state (ambiguous)
        fold = (new_dt.replace(fold=0) != new_dt.replace(fold=1))

        # Determine if it's the first occurrence of the ambiguous datetime
        if fold:
            new_dt = new_dt.replace(fold=0)

        return new_dt

    except (TypeError, OverflowError) as e:
        raise ValueError(f"Error converting datetime: {e}")

def _fromutc(self, dt):
    if not isinstance(dt, datetime.datetime):
        raise TypeError("dt must be a datetime.datetime object")
    if dt.tzinfo is None:
        raise ValueError("dt must be a timezone-aware datetime")

    # Calculate the offset for the given datetime
    offset = self.utcoffset(dt)

    # Calculate the new datetime in the new timezone
    new_dt = dt + offset

    # Check for ambiguity and determine the fold state
    fold = dt.fold
    if self.localtime(new_dt.replace(fold=0)) == self.localtime(new_dt.replace(fold=1)):
        # Ambiguous time, use the fold state to choose the correct one
        new_dt = new_dt.replace(fold=fold)
    else:
        # Not ambiguous, fold state does not matter
        new_dt = new_dt.replace(fold=0)

    return new_dt.replace(tzinfo=self)

def _fromutc(self, dt):
    if dt.tzinfo is None:
        raise ValueError("dt must be timezone-aware")
    try:
        # Convert the UTC datetime to the new timezone
        new_dt = self.localize(dt.replace(tzinfo=None))
        # Check for fold state
        fold_dt = new_dt.replace(fold=not new_dt.fold)
        if fold_dt.utcoffset() == new_dt.utcoffset() and fold_dt.dst() == new_dt.dst():
            # If the alternate fold has the same offset and dst, it's ambiguous
            new_dt = new_dt.replace(fold=True)
        return new_dt
    except Exception as e:
        raise ValueError(f"Error converting datetime: {e}")

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    try:
        tznames = namefunc()
        return [tz.encode('utf-8') if isinstance(tz, unicode) else tz for tz in tznames]
    except Exception as e:
        raise RuntimeError("An error occurred while processing tzname: {}".format(e))

