def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import subprocess
    from pathlib import Path
    import os

    try:
        tmp_path = Path(tmp_path)
        tmp_path.mkdir(parents=True, exist_ok=True)

        if not filename:
            filename = os.path.basename(archive_path)

        output_dir = tmp_path / filename.split('.')[0]
        output_dir.mkdir(parents=True, exist_ok=True)

        if archive_path.endswith('.zip'):
            subprocess.run(['unzip', '-q', archive_path, '-d', str(output_dir)], check=True)
        elif archive_path.endswith(('.tar', '.tar.gz', '.tgz')):
            subprocess.run(['tar', '-xzf', archive_path, '-C', str(output_dir)], check=True)
        elif archive_path.endswith('.tar.bz2'):
            subprocess.run(['tar', '-xjf', archive_path, '-C', str(output_dir)], check=True)
        else:
            raise ValueError("Unsupported archive format")

        return f"file://{output_dir.resolve()}"

    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to extract archive {archive_path}: {e}")
    except Exception as e:
        raise RuntimeError(f"An error occurred: {e}")

def addignored(ignored):
    try:
        # Run the git command to list ignored files
        result = subprocess.run(['git', 'check-ignore', '-v', ignored], capture_output=True, text=True, check=True)

        # Split the output into lines and extract file names
        ignored_files = [line.split()[-1] for line in result.stdout.strip().split('\n') if line]

        # Sort the list of ignored files
        ignored_files.sort()

        # Join the sorted list into a single string separated by commas
        return ','.join(ignored_files)

    except subprocess.CalledProcessError:
        # Handle the case where the git command fails
        return "Error: Unable to retrieve ignored files."
    except Exception as e:
        # Handle any other exceptions
        return f"Error: {str(e)}"

