def subprocess_run_helper(func, *args, timeout, extra_env=None):
    import subprocess
    import os

    if not callable(func):
        raise ValueError("The first argument must be a callable function.")

    if extra_env is not None and not isinstance(extra_env, dict):
        raise ValueError("The extra_env argument must be a dictionary.")

    func_module = func.__module__
    func_name = func.__name__

    # Prepare the environment
    env = os.environ.copy()
    if extra_env:
        env.update(extra_env)

    # Construct the command to run the function
    cmd = [sys.executable, '-c', f"import {func_module}; {func_module}.{func_name}({','.join(repr(arg) for arg in args)})", *args]

    try:
        result = subprocess.run(cmd, check=True, timeout=timeout, env=env, capture_output=True, text=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Subprocess failed with return code {e.returncode} and error: {e.stderr}")
    except subprocess.TimeoutExpired:
        raise TimeoutError("Subprocess exceeded the specified timeout.")

def _resolve_string(matcher):
    if not isinstance(matcher, dict) or 'name' not in matcher:
        raise ValueError("Matcher must be a dictionary with at least a 'name' key.")

    env_var_name = matcher['name']
    default_value = matcher.get('default')

    value = os.getenv(env_var_name, default_value)

    if value is None:
        raise EnvironmentError(f"Environment variable '{env_var_name}' is not set and no default value is provided.")

    return value

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    try:
        name, default = matcher
    except ValueError:
        raise ValueError("Matcher must be a tuple containing the environment variable name and an optional default value.")

    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        else:
            raise EnvironmentError(f"Environment variable '{name}' is not defined and no default value is provided.")

    return value

