def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()

    try:
        # Find all nodes that do not have a parent with the given property
        for node in graph.subjects():
            if not any(graph.predicates(node, prop)):
                roots.add(node)
    except Exception as e:
        print(f"An error occurred while finding roots: {e}")

    return roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()
    try:
        for child, _, _ in graph.triples((None, prop, None)):
            roots.add(child)
        for _, _, parent in graph.triples((None, prop, None)):
            if parent in roots:
                roots.remove(parent)
    except Exception as e:
        print(f"An error occurred: {e}")
    return roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()
    try:
        all_nodes = set(graph.subjects()) | set(graph.objects())
        non_roots = set(graph.subjects(prop))
        roots.update(all_nodes - non_roots)
    except Exception as e:
        print(f"An error occurred: {e}")
    return roots

