def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import logging
    import os
    import json

    if overrides is None:
        overrides = {}

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config = json.load(file)
                config_dict[filename] = config

                # Apply overrides if any
                config_dict[filename].update(overrides)

                # Resolve environment variables if required
                if resolve_env:
                    config_dict[filename] = {k: os.path.expandvars(v) if isinstance(v, str) else v for k, v in config_dict[filename].items()}

        except FileNotFoundError:
            log_records.append(logging.LogRecord(name=__name__, level=logging.ERROR, pathname=filename, lineno=0, msg=f"File not found: {filename}", args=(), exc_info=True))
        except json.JSONDecodeError as e:
            log_records.append(logging.LogRecord(name=__name__, level=logging.ERROR, pathname=filename, lineno=0, msg=f"Error decoding JSON from file {filename}: {e}", args=(), exc_info=True))
        except Exception as e:
            log_records.append(logging.LogRecord(name=__name__, level=logging.ERROR, pathname=filename, lineno=0, msg=f"Unexpected error loading file {filename}: {e}", args=(), exc_info=True))

    return config_dict, log_records

