        raise ValueError("Invalid input types: options_spec must be a list and args must be a dict")

    required_args = []
    for option in options_spec:
        try:
            required_when = option.get('required_when')
            if required_when:
                condition_key, expected_value = required_when.split('==')
                condition_key = condition_key.strip()
                expected_value = expected_value.strip().strip('"').strip("'")
                if condition_key in args and args[condition_key] == expected_value:
                    required_args.append(option.get('name'))
        except Exception as e:
